import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
import {COUPLED_BULK_POLICY} from '../live-paper/coupled-maker-paper-v2.mjs';import {coupledBulkCodeIdentity,openCoupledBulkHost} from '../live-paper/coupled-maker-host-v2.mjs';
import {validateUniverse} from '../live-paper/breadth.mjs';import {collectFrozenPaperFiles} from '../live-paper/frozen-paper-graph.mjs';import {verifyChainedRows} from '../live-paper/stable-maker-replay-v2.mjs';import {atomicJson,payloadHash} from '../execution/ledger.mjs';
const sha=b=>createHash('sha256').update(b).digest('hex'),runtimeDir=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),workspace=process.cwd(),marker=JSON.parse(fs.readFileSync(path.join(runtimeDir,'COLLECTOR_STOP')));
if(marker.source!=='coupled_bulk_paper_deployment_20261005')throw Error('Deployment provenance missing');
const name='baal-coupled-bulk-20261005-v2c-live',dir=path.join(runtimeDir,'coupled-bulk-cohorts',name);if(fs.existsSync(dir)||fs.existsSync(path.join(runtimeDir,'coupled-bulk-active.json')))throw Error('Existing cohort must be preserved');
