for(const[key,file]of [['tape','anonymous-trades.jsonl'],['price','market-prices.jsonl']]){const bytes=fs.readFileSync(path.join(runtimeDir,file)),rows=verifyChainedRows(bytes),tail=rows.at(-1);prefix[key]={bytes:bytes.length,hash:sha(bytes),sequence:tail?.sequence||0,tailHash:tail?.hash||''};}
const cutoff=new Date().toISOString(),bank={schemaVersion:1,mode:'coupled_bulk_history_trade_tape_paper_v2',name,cutoff,entryExpiresAt:new Date(Date.parse(cutoff)+21600000).toISOString(),tournamentId:universe.tournamentId,universe,universeSourceJson:JSON.stringify(raw),legs:universe.exchanges.map(({marketId,exchangeId})=>({marketId,exchangeId})),policy:COUPLED_BULK_POLICY,codeIdentity:coupledBulkCodeIdentity(),tapePrefix:prefix.tape,pricePrefix:prefix.price,
 selectionMode:'entire_validated_universe_bulk_stability_then_fresh_depth',independentFromPriorWallet:true,counterfactualOnly:true,executionAuthority:false,competitionOrders:0,fees:0,profitabilityEstablished:false};
const files=collectFrozenPaperFiles(workspace,['live-paper/coupled-maker-host-v2.mjs']),snapshot=payloadHash(files),frozenRoot=path.join(runtimeDir,'frozen-code',snapshot);
if(!fs.existsSync(frozenRoot)){fs.mkdirSync(frozenRoot,{recursive:true,mode:0o700});for(const[relative,hash]of Object.entries(files)){const target=path.resolve(frozenRoot,relative);if(!target.startsWith(path.resolve(frozenRoot)+path.sep))throw Error('Frozen scope');fs.mkdirSync(path.dirname(target),{recursive:true,mode:0o700});const bytes=fs.readFileSync(relative);if(sha(bytes)!==hash)throw Error('Source changed');fs.writeFileSync(target,bytes,{flag:'wx',mode:0o600});}fs.writeFileSync(path.join(frozenRoot,'manifest.json'),JSON.stringify({schemaVersion:1,files},null,2)+'\n',{flag:'wx',mode:0o600});}
const indexFile=path.join(runtimeDir,'frozen-code','index.json'),index=JSON.parse(fs.readFileSync(indexFile));index.banks[payloadHash(bank)]={snapshot};atomicJson(indexFile,index);
fs.mkdirSync(dir,{recursive:true,mode:0o700});atomicJson(path.join(dir,'bank.json'),bank);atomicJson(path.join(runtimeDir,'coupled-bulk-active.json'),{schemaVersion:1,cohort:name,bankHash:payloadHash(bank)});
const host=openCoupledBulkHost({runtimeDir}),status=host.status(),wallet=status.wallets.COUPLED;if(wallet.fills||wallet.cash!=='100.000000'||wallet.pairedRedemptions)throw Error('Unexpected new shared wallet state');
fs.writeFileSync('data/coupled-bulk-live-bank-v2c-20261005.json',JSON.stringify({schemaVersion:1,at:cutoff,bankHash:payloadHash(bank),snapshot,bank,initialPaperState:{COUPLED:{cash:wallet.cash,fills:0,pairedRedemptions:0}},originalWalletsReset:false,newServices:0,officialActivationChanged:false},null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({cohort:name,cutoff,bankHash:payloadHash(bank),scope:bank.legs.length,frozenFiles:Object.keys(files).length,sourceFrontiers:status.sourceFrontiers,networkRequests:0,competitionOrders:0}));
